   [76]={next_id=77, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [77]={next_id=78, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="烁曦沉默了一会，轻轻摇头。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [78]={next_id=79, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="要是我说不累，贵公一定会觉得我在吹嘘……", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [79]={next_id=80, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="女孩咬了咬嘴唇，起身坐到了你的身边，指尖轻轻与你相依。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [80]={next_id=81, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可这份重担时刻压在身上鞭策着我，我只能压抑想要发泄的心，告诫自己不能懈怠。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [81]={next_id=82, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="压抑到现在……反而有些看不清我自己了，直到与贵公一同回到康斯坦丁家……", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [82]={next_id=83, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="对我来说，这几天的日子如同梦幻一般，我可以抛却自己的身份，和贵公一起做自己想做的事，被贵公照顾着……", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [83]={next_id=84, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她侧过脸看向你，瞳孔中波光粼粼，仿佛鼓起了极大的勇气。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [84]={next_id=85, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="哪怕是假的身份，哪怕结束的那天终会到来……我也绝不后悔。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [85]={next_id=86, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="有贵公在我的身边，我由衷地感到……幸福。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [86]={next_id=87, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这是“告白”吗？她不知道，也不想去纠结。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [87]={next_id=88, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="没有任何铺垫，没有任何前奏，甚至连她自己都没料到——明明前一秒还在聊小说里的骑士铠甲，下一秒，压在心底的话就这么脱口而出。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [88]={next_id=89, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="像堤坝突然决了口，任何理智都拦不住。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [89]={next_id=90, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="从他来到维拉提亚的那一天起，那颗始终坚硬如铁的心便开始了躁动。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她本以为只是对强者的尊敬，可在那天的生死之间，他将后背交给自己的那一刻，那份心意便再也藏不住了，在心底里疯长。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她想要继续压抑下去，然而那一夜唇间的触感，指尖的温度，都在提醒着她——", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="就像是选择成为骑士那样，如果这一刻不向他倾诉自己的心意，她一定会后悔一生。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="女孩的指尖悄悄收紧，连耳尖都开始发烫，声音带着点自己都没察觉的颤抖。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="贵公，我知道……这话很突然，也很荒唐。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [95]={next_id=96, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但我……还是想问你——", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [96]={next_id=97, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这场戏……可以一直演下去吗？", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [97]={next_id=98, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她问出来了。当内心不再压抑，当爱意悄然绽放。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我不是想给你添麻烦，也不是想逼你做什么，我只是……", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我只是怕…… 要是现在不说，以后就没机会说了。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这场戏结束后，我们可能又要回到各自的战场，我怕到时候……我又会变回那个只会扛着骑枪的命星骑士，再也没勇气跟你说这些。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的目光牢牢锁在你脸上，有忐忑在眼底晃动，有期待在悄悄发芽，还有一丝孤注一掷。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [102]={next_id=103, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="哪怕你拒绝，她也想把这句话说出来，至少不会在日后想起时，因为 “没说出口” 而后悔。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [103]={next_id=104, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="房间里的声响似乎都停了下来，只剩下她轻轻的呼吸声。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [104]={next_id=-1, abreast_id={105}, pType =2, cg_type =10, dialog=1, msg="她在等待你的回答。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [105]={next_id=107, abreast_id={}, pType =3, cg_type =10, dialog=1, msg="告诉她你的心意", msg_color="", msg_size=0, talker="选项", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [106]={next_id=-1, abreast_id={}, pType =4, cg_type =10, dialog=1, msg="null", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [107]={next_id=108, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你没有让她等太久。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [108]={next_id=109, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="想演多久我都陪你，一天，一个星期，一个月，一年……或者说，一辈子。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [109]={next_id=110, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我都陪你演下去，克拉伦斯·康斯坦丁小姐。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [110]={next_id=111, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……！！", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [111]={next_id=112, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="话音未落，你握住了颤抖的手——她瞬间僵住，不可置信地抬头看向你。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [112]={next_id=113, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="贵公……是真的吗？", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [113]={next_id=114, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你、你不是在安慰我？也不是在…… 开玩笑？", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [114]={next_id=115, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="绝非有假。因为我和你一样，也在这段不长的时间里度过了非常快乐、幸福的日子。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [115]={next_id=116, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以……即便离开了这里，面对星都，面对莱斯坦斯，面对所有人的议论——", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [116]={next_id=117, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这场只属于你我的戏，我也不想要结束。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [117]={next_id=118, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她没有松开你的手，而是主动上前，把另一只手覆在你的手背上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [118]={next_id=119, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="谢谢你，贵公……有你在，我的骑士之路一定会走更远。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [119]={next_id=120, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她扬起脸，再次鼓起勇气靠近你，与你唇瓣相接。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [120]={next_id=121, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这一次，她不再被动，不再紧张，而是带着生涩地主动出击，和你的舌尖相互缠绕。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [121]={next_id=122, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="经历了磕磕绊绊而成长为命星骑士的克拉伦斯·康斯坦丁，在这一刻终于得到了自己想要的回应。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [122]={next_id=123, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="渐渐地，她变得激进，变得贪心，变得肆无忌惮——压抑了太久的爱意，在此刻化作无底洞的索取。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [123]={next_id=124, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="唇瓣分离时，带着一丝不易察觉的黏连。烁曦急促地喘着气，胸口微微起伏，方才因亲吻而憋红的脸颊，在阳光下像熟透的樱桃。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [124]={next_id=125, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="呼……呼……", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [125]={next_id=126, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="差点……要窒息了……", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [126]={next_id=127, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="哈……总觉得……烁曦好像打开了什么不得了的开关啊……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [127]={next_id=128, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="开，开关？！贵公不要说一些奇怪的话……", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 36.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
