   [139]={next_id=140, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="咳咳……快到午饭的时间点了，琳梅尔阿姨——", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [140]={next_id=141, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="——咚咚，敲门声恰好响起，琳梅尔提醒你们用餐的话语从门外传来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [141]={next_id=142, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="于是你牵起烁曦的手，为她捋好了额发。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [142]={next_id=143, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="还记得昨晚说的吗？走吧，一会你就知道了。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
