   [182]={next_id=183, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="就在这时，餐厅的侧门被推开。老康斯坦丁走了进来，身上穿着一件洗得发白的亚麻厨师服，手里端着一个白瓷盘，盘里是一碗冒着热气的南瓜汤。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [183]={next_id=184, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="汤面上撒了少许肉桂粉，正是烁曦小时候最爱的做法。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
