   [263]={next_id=264, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="过了会，她扬起嘴角，认真地向你伸出手。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [264]={next_id=265, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你有些疑惑，但还是回握住她的手掌，却不想她突然贴紧了你，在你的唇角留下独属于她的吻痕。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [265]={next_id=266, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这个吻很轻，却格外坚定。没有之前的生涩躲闪，也没有过度的缠绵，只有克制的触碰与不可掩饰的热情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [266]={next_id=267, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="像烈阳穿透云层，带着她独有的炽热，将所有未说出口的心意，都融进这短暂却深刻的触碰里。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1002.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
